// Shared per-lead send limiter. Every worker on the machine points at the same STATE_DIR.
// One JSON file per lead lists that lead's counted send slots. A mkdir-based lock
// serializes the read-modify-write for each lead across processes.
//
// What counts: a reservation counts from the moment it is granted until release() removes it.
// Denied calls never count. A held slot whose worker crashed still counts, because the
// message may already have gone out.
// Window: sliding. A slot stops counting once it is older than windowHours.

import { mkdir, readFile, writeFile, rename, rm, stat } from 'node:fs/promises';
import { randomUUID } from 'node:crypto';
import path from 'node:path';
import { setTimeout as sleep } from 'node:timers/promises';

const MINUTE_MS = 60_000;
const HOUR_MS = 60 * MINUTE_MS;
const LOCK_STALE_MS = 10_000;
const KEY_PATTERN = /^[A-Za-z0-9_-]+$/;

export async function reserve(request, now) {
  const { userId, maxPerWindow, windowHours, minGapMinutes } = request ?? {};
  if (typeof userId !== 'string' || userId === '') throw new TypeError('userId must be a non-empty string');
  if (!Number.isInteger(maxPerWindow) || maxPerWindow < 0) throw new TypeError('maxPerWindow must be an integer >= 0');
  if (!(windowHours > 0)) throw new TypeError('windowHours must be > 0');
  if (!(minGapMinutes >= 0)) throw new TypeError('minGapMinutes must be >= 0');
  if (!(now instanceof Date) || Number.isNaN(now.getTime())) throw new TypeError('now must be a valid Date');

  const nowMs = now.getTime();
  const windowMs = windowHours * HOUR_MS;
  const gapMs = minGapMinutes * MINUTE_MS;
  const key = leadKey(userId);
  const dir = await prepareStateDir();

  return withLock(dir, key, async () => {
    const history = await loadHistory(dir, key);
    // Keep every send any limit could still see, for the longest span any caller has asked for.
    history.retainMs = Math.max(history.retainMs, windowMs, gapMs);
    history.sends = history.sends.filter((s) => s.at > nowMs - history.retainMs);

    const inWindow = history.sends.filter((s) => s.at > nowMs - windowMs).length;
    const lastAt = history.sends.reduce((max, s) => Math.max(max, s.at), -Infinity);

    let reason = null;
    if (inWindow >= maxPerWindow) reason = 'window_limit_reached';
    else if (history.sends.length > 0 && nowMs - lastAt < gapMs) reason = 'min_gap_not_elapsed';

    if (reason) {
      await saveHistory(dir, key, history);
      return { allowed: false, reason, reservationId: null };
    }

    const reservationId = `${key}.${randomUUID()}`;
    history.sends.push({ id: reservationId, at: nowMs });
    await saveHistory(dir, key, history);
    return { allowed: true, reason: null, reservationId };
  });
}

export async function release(reservationId) {
  if (typeof reservationId !== 'string') return false;
  const cut = reservationId.lastIndexOf('.');
  const key = cut > 0 ? reservationId.slice(0, cut) : '';
  if (!KEY_PATTERN.test(key)) return false;

  const dir = await prepareStateDir();
  return withLock(dir, key, async () => {
    const history = await loadHistory(dir, key);
    const before = history.sends.length;
    history.sends = history.sends.filter((s) => s.id !== reservationId);
    if (history.sends.length === before) return false;
    await saveHistory(dir, key, history);
    return true;
  });
}

function leadKey(userId) {
  return Buffer.from(userId, 'utf8').toString('base64url');
}

async function prepareStateDir() {
  const dir = process.env.STATE_DIR;
  if (!dir) throw new Error('STATE_DIR is not set');
  await mkdir(path.join(dir, 'leads'), { recursive: true });
  await mkdir(path.join(dir, 'locks'), { recursive: true });
  return dir;
}

function leadFile(dir, key) {
  return path.join(dir, 'leads', `${key}.json`);
}

async function loadHistory(dir, key) {
  try {
    return JSON.parse(await readFile(leadFile(dir, key), 'utf8'));
  } catch (err) {
    if (err.code === 'ENOENT') return { retainMs: 0, sends: [] };
    throw err;
  }
}

// Write to a temp file, then rename, so a reader never sees a half-written file.
async function saveHistory(dir, key, history) {
  const file = leadFile(dir, key);
  const tmp = `${file}.${process.pid}.${randomUUID()}.tmp`;
  await writeFile(tmp, JSON.stringify(history));
  await rename(tmp, file);
}

async function withLock(dir, key, body) {
  const lockPath = path.join(dir, 'locks', `${key}.lock`);
  for (;;) {
    try {
      await mkdir(lockPath);
      break;
    } catch (err) {
      if (err.code !== 'EEXIST') throw err;
      if (await removeIfStale(lockPath)) continue;
      await sleep(2 + Math.random() * 8);
    }
  }
  try {
    return await body();
  } finally {
    await rm(lockPath, { recursive: true, force: true });
  }
}

// Returns true when the lock is gone (removed here, or already gone), so the caller retries at once.
async function removeIfStale(lockPath) {
  try {
    const { mtimeMs } = await stat(lockPath);
    if (Date.now() - mtimeMs < LOCK_STALE_MS) return false;
    await rm(lockPath, { recursive: true, force: true });
    return true;
  } catch (err) {
    if (err.code === 'ENOENT') return true;
    throw err;
  }
}

const BOT = '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/knock-inv-g4-3/bot.mjs';
const [, , userId, max, gap, count, nowIso] = process.argv;
const { reserve } = await import(BOT);
const out = [];
for (let i = 0; i < Number(count); i++) {
  out.push(await reserve({ userId, maxPerWindow: Number(max), windowHours: 24, minGapMinutes: Number(gap) }, new Date(nowIso)));
}
console.log(JSON.stringify(out));

import assert from 'node:assert/strict';
import { mkdtemp, mkdir, utimes } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';

const BOT = '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/knock-inv-g4-3/bot.mjs';
const WORKER = '/tmp/bot-check/worker.mjs';
const exec = promisify(execFile);
const { reserve, release } = await import(BOT);

const STATE = await mkdtemp(path.join(tmpdir(), 'bot-state-'));
process.env.STATE_DIR = STATE;

const H = 3_600_000;
const M = 60_000;
const T0 = new Date('2026-10-22T09:00:00Z').getTime();
const at = (ms) => new Date(T0 + ms);
const req = (userId, o = {}) => ({ userId, maxPerWindow: 3, windowHours: 24, minGapMinutes: 0, ...o });
const denied = (reason) => ({ allowed: false, reason, reservationId: null });

// A. Window cap: pending reservations count, 4th is denied.
for (let i = 0; i < 3; i++) {
  const r = await reserve(req('lead_a'), at(i * 1000));
  assert.equal(r.allowed, true);
  assert.equal(r.reason, null);
  assert.match(r.reservationId, /\./);
}
assert.deepEqual(await reserve(req('lead_a'), at(5000)), denied('window_limit_reached'));
console.log('A ok: window cap');

// B. Min gap; denied attempts do not count toward the gap.
const b = { userId: 'lead_b', maxPerWindow: 10, minGapMinutes: 90 };
assert.equal((await reserve(b, at(0))).allowed, true);
assert.deepEqual(await reserve(b, at(30 * M)), denied('min_gap_not_elapsed'));
assert.deepEqual(await reserve(b, at(60 * M)), denied('min_gap_not_elapsed'));
assert.equal((await reserve(b, at(90 * M))).allowed, true);
console.log('B ok: min gap, denials not counted');

// C. Sliding window: a slot frees once it is older than windowHours.
const c = { userId: 'lead_c', maxPerWindow: 2, minGapMinutes: 0 };
assert.equal((await reserve(c, at(0))).allowed, true);
assert.equal((await reserve(c, at(1 * H))).allowed, true);
assert.deepEqual(await reserve(c, at(2 * H)), denied('window_limit_reached'));
assert.equal((await reserve(c, at(24 * H + M))).allowed, true); // t0 expired, t+1h still counts
assert.deepEqual(await reserve(c, at(24 * H + 2 * M)), denied('window_limit_reached'));
console.log('C ok: sliding window');

// D. release frees the slot; release is idempotent; unknown or malformed ids return false.
const d = { userId: 'lead_d', maxPerWindow: 1, minGapMinutes: 0 };
const d1 = await reserve(d, at(0));
assert.deepEqual(await reserve(d, at(1000)), denied('window_limit_reached'));
assert.equal(await release(d1.reservationId), true);
assert.equal((await reserve(d, at(2000))).allowed, true);
assert.equal(await release(d1.reservationId), false);
assert.equal(await release('not-a-reservation'), false);
assert.equal(await release('../etc.abc'), false);
assert.equal(await release(undefined), false);
console.log('D ok: release');

// E. Releasing a slot also lifts the min-gap block.
const e = { userId: 'lead_e', maxPerWindow: 10, minGapMinutes: 90 };
const e1 = await reserve(e, at(0));
assert.deepEqual(await reserve(e, at(10 * M)), denied('min_gap_not_elapsed'));
await release(e1.reservationId);
assert.equal((await reserve(e, at(10 * M))).allowed, true);
console.log('E ok: release lifts gap');

// F. Limits are per call; a looser call at the same moment is allowed.
assert.equal((await reserve({ userId: 'lead_f', maxPerWindow: 1, minGapMinutes: 0 }, at(0))).allowed, true);
assert.deepEqual(await reserve({ userId: 'lead_f', maxPerWindow: 1, minGapMinutes: 0 }, at(1000)), denied('window_limit_reached'));
assert.equal((await reserve({ userId: 'lead_f', maxPerWindow: 5, minGapMinutes: 0 }, at(2000))).allowed, true);
console.log('F ok: per-call limits');

// G. Stale lock from a crashed worker is cleared; a fresh lock is respected.
const lockKey = Buffer.from('lead_g').toString('base64url');
const lockDir = path.join(STATE, 'locks', `${lockKey}.lock`);
await mkdir(lockDir, { recursive: true });
const hourAgo = new Date(Date.now() - H);
await utimes(lockDir, hourAgo, hourAgo);
assert.equal((await reserve(req('lead_g'), at(0))).allowed, true);
console.log('G ok: stale lock cleared');

// H. Restart: a separate process sees the history written by an earlier one.
const h = { maxPerWindow: 2, gap: 0 };
const first = JSON.parse((await exec(process.execPath, [WORKER, 'lead_h', '2', '0', '1', at(0).toISOString()])).stdout);
assert.equal(first[0].allowed, true);
assert.equal((await reserve(req('lead_h', { maxPerWindow: 2 }), at(1000))).allowed, true);
assert.deepEqual(await reserve(req('lead_h', { maxPerWindow: 2 }), at(2000)), denied('window_limit_reached'));
console.log('H ok: survives restart across processes');

// I. Concurrency: 12 processes x 5 calls each at the same instant.
const runWorkers = async (userId, max, gap) => {
  const runs = await Promise.all(Array.from({ length: 12 }, () =>
    exec(process.execPath, [WORKER, userId, String(max), String(gap), '5', at(0).toISOString()])));
  return runs.flatMap((r) => JSON.parse(r.stdout));
};
const cap = await runWorkers('lead_i', 3, 0);
assert.equal(cap.filter((r) => r.allowed).length, 3, 'window cap must hold under concurrency');
assert.ok(cap.every((r) => r.allowed || r.reason === 'window_limit_reached'));

const gapped = await runWorkers('lead_j', 10, 90);
assert.equal(gapped.filter((r) => r.allowed).length, 1, 'min gap must hold under concurrency');
assert.ok(gapped.every((r) => r.allowed || r.reason === 'min_gap_not_elapsed'));
console.log('I ok: concurrency (12 procs x 5 calls)');

// J. Input validation.
await assert.rejects(reserve({ userId: '', maxPerWindow: 1, windowHours: 1, minGapMinutes: 0 }, new Date()), TypeError);
await assert.rejects(reserve({ userId: 'x', maxPerWindow: -1, windowHours: 1, minGapMinutes: 0 }, new Date()), TypeError);
await assert.rejects(reserve({ userId: 'x', maxPerWindow: 1, windowHours: 1, minGapMinutes: 0 }, '2026-01-01'), TypeError);
console.log('J ok: validation');

// K. No STATE_DIR is an error, not a silent local fallback.
const saved = process.env.STATE_DIR;
delete process.env.STATE_DIR;
await assert.rejects(reserve(req('lead_k'), new Date()), /STATE_DIR/);
process.env.STATE_DIR = saved;
console.log('K ok: STATE_DIR required');

console.log('ALL CHECKS PASSED');
